// ADD new helper that returns Vec<Action> for proper sequencing:
/// Create actions for DAO space registration (returns multiple events in order)
pub fn dao_space_created(
    space_id: SpaceId,
    dao_type: [u8; 32],  // keccak256("DAO_SPACE")
    version: &[u8],
    initial_editors: Vec<Address>,
    initial_members: Vec<Address>,
) -> Vec<Action> {
    let mut actions = Vec::new();

    // 1. SPACE_ID_REGISTERED (from registry)
    actions.push(Action {
        from_id: vec![0u8; 16],
        to_id: space_id.to_vec(),
        action: actions::SPACE_REGISTERED.to_vec(),
        topic: vec![0u8; 32],  // No owner for DAO
        data: vec![],
    });

    // 2. SPACE_TYPE_DECLARED (from registry)
    actions.push(Action {
        from_id: space_id.to_vec(),
        to_id: space_id.to_vec(),
        action: actions::SPACE_TYPE_DECLARED.to_vec(),
        topic: dao_type.to_vec(),
        data: version.to_vec(),
    });

    // 3. EDITOR_ADDED for each initial editor
    for editor in initial_editors {
        actions.push(editor_added(space_id, editor));
    }

    // 4. MEMBER_ADDED for each initial member
    for member in initial_members {
        actions.push(member_added(space_id, member));
    }

    actions
}
